 public void test_annotated_surface_bounds_atomic_copy_legacy_and_packet_budget()
 {
  foreach(var (ns,path)in new[]{("Confectory.RunSurface","run-surface"),("Confectory.FrameControl","frame-control")}){f.ExtraRegistry[ns]=Path.Combine(Fixture.Repo,"packs",path,"pack.cpack");f.Packs["App"].Dependencies[ns]="0.1.0";}
  f.Main("");f.Add("App","implementation","MainBody","""
  implementation App::MainBody for App::Main () -> int {
  import Confectory.RunSurface::Open as Open (string) -> string;import Confectory.RunSurface::Present as Present (string,int,int,string) -> long;import Confectory.RunSurface::PresentBounds as PresentBounds (string,int,int,string,int[]) -> long;import Confectory.RunSurface::ConfigureSize as ConfigureSize (string,int,int) -> void;import Confectory.RunSurface::Close as Close (string) -> void;import Confectory.FrameControl::Open as OpenFrame () -> string;import Confectory.FrameControl::Close as CloseFrame (string) -> void;body common "main.csbody";}
  """);f.Body("App","main.csbody","""
  void Check(bool value,string label){if(!value)throw new Exception(label);}bool Denied(Action action){try{action();return false;}catch(ArgumentException){return true;}}
  string pipe="confectory-bounds-"+Guid.NewGuid().ToString("N"),secret=new string('a',64),handle=new string('b',32);Environment.SetEnvironmentVariable("CONFECTORY_FRAME_PIPE",pipe);Environment.SetEnvironmentVariable("CONFECTORY_FRAME_SECRET",secret);Environment.SetEnvironmentVariable("CONFECTORY_FRAME_HANDLE",handle);
  string frame=calls.OpenFrame.Invoke(),owner=calls.Open.Invoke(frame);
  System.Text.Json.Nodes.JsonObject Read(string operation,string runtime="",string cursor=""){
   using var deadline=new System.Threading.CancellationTokenSource(3000);using var stream=new System.IO.Pipes.NamedPipeClientStream(".",pipe,System.IO.Pipes.PipeDirection.InOut,System.IO.Pipes.PipeOptions.Asynchronous|System.IO.Pipes.PipeOptions.CurrentUserOnly);stream.ConnectAsync(deadline.Token).GetAwaiter().GetResult();var query=new System.Text.Json.Nodes.JsonObject{["version"]=1,["handle"]=handle,["secret"]=secret,["request"]=Guid.NewGuid().ToString("N"),["operation"]=operation,["runtime"]=runtime,["cursor"]=cursor,["sequence"]=0};byte[] bytes=System.Text.Encoding.UTF8.GetBytes(query.ToJsonString()),header=new byte[4];System.Buffers.Binary.BinaryPrimitives.WriteInt32LittleEndian(header,bytes.Length);stream.WriteAsync(header,deadline.Token).AsTask().GetAwaiter().GetResult();stream.WriteAsync(bytes,deadline.Token).AsTask().GetAwaiter().GetResult();stream.ReadExactlyAsync(header,deadline.Token).AsTask().GetAwaiter().GetResult();int length=System.Buffers.Binary.BinaryPrimitives.ReadInt32LittleEndian(header);Check(length<=1400000,"existing packet budget unchanged");bytes=new byte[length];stream.ReadExactlyAsync(bytes,deadline.Token).AsTask().GetAwaiter().GetResult();return System.Text.Json.Nodes.JsonNode.Parse(bytes)!.AsObject();
  }
  try{
   string runtime=Read("observe")["runtime"]!.ToString(),image=Convert.ToBase64String(new byte[512*512*4]);calls.ConfigureSize.Invoke(owner,512,512);var rectangles=new int[64];for(int i=0;i<64;i+=4){rectangles[i]=511;rectangles[i+1]=511;rectangles[i+2]=1;rectangles[i+3]=1;}Check(calls.PresentBounds.Invoke(owner,512,512,image,rectangles)==1,"one atomic publication");Array.Fill(rectangles,0);var first=Read("surface",runtime);Check(first["bounds"]!["rectangles"]![0]!.GetValue<int>()==511&&first["bounds"]!["rectangles"]!.AsArray().Count==64,"bounds copied and maximum pixels/bounds/rate/resize fit original packet");string cursor=first["cursor"]!.ToString();
   foreach(var bad in new[]{new int[]{-1,0,1,1},new int[]{0,0,513,1},new int[]{0,0,1},new int[68],new int[]{int.MaxValue,0,int.MaxValue,1}})Check(Denied(()=>calls.PresentBounds.Invoke(owner,512,512,image,bad)),"invalid bounds refused before publish");Check(Denied(()=>calls.PresentBounds.Invoke(owner,512,512,"AAAA",new[]{0,0,1,1})),"invalid pixels refused before publish");var same=Read("surface",runtime,cursor);Check(same["unchanged"]!.GetValue<bool>()&&same["revision"]!.ToString()=="1"&&same["bounds"]!["rectangles"]![0]!.GetValue<int>()==511,"failed writes preserve revision/pixels/bounds");
   Check(calls.Present.Invoke(owner,512,512,image)==2,"legacy ABI retained");Check(Read("surface",runtime)["bounds"]is null,"new legacy frame opts out explicitly");Check(calls.PresentBounds.Invoke(owner,512,512,image,Array.Empty<int>())==3&&Read("surface",runtime)["bounds"]!["rectangles"]!.AsArray().Count==0,"empty visible scene is valid");
  }finally{calls.Close.Invoke(owner);calls.CloseFrame.Invoke(frame);}Console.WriteLine("Annotated bounds atomic copy/legacy/shape/maximum authenticated packet PASS");return 0;
  """);f.Sync();Output(Build(),"Annotated bounds atomic copy/legacy/shape/maximum authenticated packet PASS");
 }
 public void test_software_rate_counts_publications_not_reads_or_control_frames()
 {
  foreach(var (ns,path)in new[]{("Confectory.RunSurface","run-surface"),("Confectory.FrameControl","frame-control")}){f.ExtraRegistry[ns]=Path.Combine(Fixture.Repo,"packs",path,"pack.cpack");f.Packs["App"].Dependencies[ns]="0.1.0";}
  f.Main("");f.Add("App","implementation","MainBody","""
  implementation App::MainBody for App::Main () -> int {
  import Confectory.RunSurface::Open as Open (string) -> string;import Confectory.RunSurface::Present as Present (string,int,int,string) -> long;import Confectory.RunSurface::Close as Close (string) -> void;import Confectory.FrameControl::Open as OpenFrame () -> string;import Confectory.FrameControl::Close as CloseFrame (string) -> void;body common "main.csbody";}
  """);f.Body("App","main.csbody","""
  void Check(bool b,string message){if(!b)throw new Exception(message);}
  string pipe="confectory-rate-"+Guid.NewGuid().ToString("N"),secret=new string('a',64),handle=new string('b',32);Environment.SetEnvironmentVariable("CONFECTORY_FRAME_PIPE",pipe);Environment.SetEnvironmentVariable("CONFECTORY_FRAME_SECRET",secret);Environment.SetEnvironmentVariable("CONFECTORY_FRAME_HANDLE",handle);
  string frame=calls.OpenFrame.Invoke(),owner=calls.Open.Invoke(frame);
  System.Text.Json.Nodes.JsonObject Read(string operation,string runtime="",string cursor=""){
   using var deadline=new System.Threading.CancellationTokenSource(2000);using var stream=new System.IO.Pipes.NamedPipeClientStream(".",pipe,System.IO.Pipes.PipeDirection.InOut,System.IO.Pipes.PipeOptions.Asynchronous|System.IO.Pipes.PipeOptions.CurrentUserOnly);stream.ConnectAsync(deadline.Token).GetAwaiter().GetResult();var query=new System.Text.Json.Nodes.JsonObject{["version"]=1,["handle"]=handle,["secret"]=secret,["request"]=Guid.NewGuid().ToString("N"),["operation"]=operation,["runtime"]=runtime,["cursor"]=cursor,["sequence"]=0};byte[] bytes=System.Text.Encoding.UTF8.GetBytes(query.ToJsonString()),header=new byte[4];System.Buffers.Binary.BinaryPrimitives.WriteInt32LittleEndian(header,bytes.Length);stream.WriteAsync(header,deadline.Token).AsTask().GetAwaiter().GetResult();stream.WriteAsync(bytes,deadline.Token).AsTask().GetAwaiter().GetResult();stream.ReadExactlyAsync(header,deadline.Token).AsTask().GetAwaiter().GetResult();int length=System.Buffers.Binary.BinaryPrimitives.ReadInt32LittleEndian(header);Check(length<4096,"bounded rate metadata");bytes=new byte[length];stream.ReadExactlyAsync(bytes,deadline.Token).AsTask().GetAwaiter().GetResult();return System.Text.Json.Nodes.JsonNode.Parse(bytes)!.AsObject();
  }
  try{
   string runtime=Read("observe")["runtime"]!.ToString();Check(calls.Present.Invoke(owner,1,1,"AAAAAA==")==1,"first actual publication");var first=Read("surface",runtime);Check(first["renderRate"]!["observation"]!.ToString()=="1","first observation");
   System.Threading.Thread.Sleep(1100);long revision=1;for(int i=0;i<7;i++)revision=calls.Present.Invoke(owner,1,1,"AAAAAA==");bool denied=false;try{calls.Present.Invoke(owner,1,1,"AAAA");}catch(ArgumentException){denied=true;}Check(denied,"bad Present rejected before rate accounting");var current=Read("surface",runtime);Check(current["revision"]!.ToString()=="8"&&current["renderRate"]!["frames"]!.ToString()=="7","exact successful publications in fresh window");Check(current["renderRate"]!["ready"]!.GetValue<bool>(),"real warmup elapsed");string cursor=current["cursor"]!.ToString();
   for(int i=0;i<12;i++){var same=Read("surface",runtime,cursor);Check(same["unchanged"]!.GetValue<bool>()&&same["pixels"]is null&&same["revision"]!.ToString()=="8"&&same["renderRate"]!["frames"]!.ToString()=="7","reads neither publish nor count control frames");Check(same["renderRate"]!["observation"]!.GetValue<string>()!=current["renderRate"]!["observation"]!.GetValue<string>(),"fresh observation without new pixels");current=same;}
   System.Threading.Thread.Sleep(1100);var idle=Read("surface",runtime,cursor);Check(idle["renderRate"]!["frames"]!.ToString()=="0"&&idle["revision"]!.ToString()=="8","idle window decays without a timer or new Present");var control=Read("observe");Check(control["frame"]!.ToString()=="0"&&control["ack"]!.GetValue<int>()==0,"software publications are not cooperative frame completions");
   string previous=first["runtime"]!.ToString();calls.Close.Invoke(owner);Check(!Read("surface",runtime)["available"]!.GetValue<bool>(),"retired output has no rate");owner=calls.Open.Invoke(frame);calls.Present.Invoke(owner,1,1,"AAAAAA==");var next=Read("surface",runtime);Check(next["runtime"]!.ToString()!=previous&&next["renderRate"]!["observation"]!.ToString()=="1","new publisher resets rate identity");
  }finally{calls.Close.Invoke(owner);calls.CloseFrame.Invoke(frame);}Console.WriteLine("Software rate actual authenticated pipe/publication/read/control/idle/replacement PASS");return 0;
  """);f.Sync();Output(Build(),"Software rate actual authenticated pipe/publication/read/control/idle/replacement PASS");
 }
 public void test_size_opt_in_thread_copy_once_and_legacy_output()
 {
  foreach(var (ns,path)in new[]{("Confectory.RunSurface","run-surface"),("Confectory.FrameControl","frame-control")}){f.ExtraRegistry[ns]=Path.Combine(Fixture.Repo,"packs",path,"pack.cpack");f.Packs["App"].Dependencies[ns]="0.1.0";}
  f.Main("");f.Add("App","implementation","MainBody","""
  implementation App::MainBody for App::Main () -> int {
  import Confectory.RunSurface::Open as Open (string) -> string;import Confectory.RunSurface::Present as Present (string,int,int,string) -> long;import Confectory.RunSurface::Close as Close (string) -> void;import Confectory.RunSurface::ConfigureSize as ConfigureSize (string,int,int) -> void;import Confectory.RunSurface::RequestedSize as RequestedSize (string) -> int[];import Confectory.FrameControl::Open as OpenFrame () -> string;import Confectory.FrameControl::Close as CloseFrame (string) -> void;body common "main.csbody";}
  """);f.Body("App","main.csbody","""
  foreach(string n in new[]{"PIPE","SECRET","HANDLE"})Environment.SetEnvironmentVariable("CONFECTORY_FRAME_"+n,null);
  void Check(bool b,string m){if(!b)throw new Exception(m);}bool Denied(Action a){try{a();return false;}catch(InvalidOperationException){return true;}catch(ArgumentException){return true;}}
  string frame=calls.OpenFrame.Invoke(),owner=calls.Open.Invoke(frame);try{Check(Denied(()=>calls.RequestedSize.Invoke(owner)),"legacy is not implicitly resizable");Check(Denied(()=>calls.ConfigureSize.Invoke(owner,0,240)),"initial shape budget");calls.ConfigureSize.Invoke(owner,64,36);int[] size=calls.RequestedSize.Invoke(owner);size[0]=512;Check(calls.RequestedSize.Invoke(owner)[0]==64,"copied requested size");Check(Denied(()=>calls.ConfigureSize.Invoke(owner,240,240)),"configure once");bool refused=false;System.Threading.Tasks.Task.Run(()=>{try{calls.RequestedSize.Invoke(owner);}catch(InvalidOperationException){refused=true;}}).GetAwaiter().GetResult();Check(refused,"consume on creator thread");Check(calls.Present.Invoke(owner,64,36,Convert.ToBase64String(new byte[64*36*4]))==1,"original explicit render");}finally{calls.Close.Invoke(owner);}Check(Denied(()=>calls.RequestedSize.Invoke(owner)),"closed size owner");string wide=calls.Open.Invoke(frame);Check(Denied(()=>calls.ConfigureSize.Invoke(wide,640,640)),"initial fixed pixel budget");calls.ConfigureSize.Invoke(wide,640,360);Check(calls.RequestedSize.Invoke(wide)[0]==640,"wide explicit initial dimensions");calls.Close.Invoke(wide);string legacy=calls.Open.Invoke(frame);calls.Present.Invoke(legacy,1,1,"AAAAAA==");Check(Denied(()=>calls.ConfigureSize.Invoke(legacy,240,240)),"no late implicit opt-in");calls.Close.Invoke(legacy);calls.CloseFrame.Invoke(frame);Console.WriteLine("Explicit size opt-in/thread/copy/once/legacy PASS");return 0;
  """);f.Sync();var report=Build();Output(report,"Explicit size opt-in/thread/copy/once/legacy PASS");
 }
 public void test_explicit_software_surface_owner_budget_copy_and_close()
 {
  f.ExtraRegistry["Confectory.RunSurface"]=Path.Combine(Fixture.Repo,"packs/run-surface/pack.cpack");f.Packs["App"].Dependencies["Confectory.RunSurface"]="0.1.0";
  f.ExtraRegistry["Confectory.FrameControl"]=Path.Combine(Fixture.Repo,"packs/frame-control/pack.cpack");f.Packs["App"].Dependencies["Confectory.FrameControl"]="0.1.0";f.Main("");f.Add("App","implementation","MainBody","""
  implementation App::MainBody for App::Main () -> int {
  import Confectory.RunSurface::Open as Open (string) -> string;import Confectory.RunSurface::Present as Present (string,int,int,string) -> long;import Confectory.RunSurface::Close as Close (string) -> void;import Confectory.FrameControl::Open as OpenFrame () -> string;import Confectory.FrameControl::Close as CloseFrame (string) -> void;body common "main.csbody";}
  """);f.Body("App","main.csbody","""
  foreach(string n in new[]{"PIPE","SECRET","HANDLE"})Environment.SetEnvironmentVariable("CONFECTORY_FRAME_"+n,null);
  void Check(bool b,string m){if(!b)throw new Exception(m);}bool Denied(Action op){try{op();return false;}catch(ArgumentException){return true;}catch(InvalidOperationException){return true;}catch(FormatException){return true;}}
  string loop=calls.OpenFrame.Invoke(),owner=calls.Open.Invoke(loop);try{
   Check(Denied(()=>calls.Open.Invoke(loop)),"second implicit output rejected");var bytes=new byte[512*512*4];Array.Fill(bytes,(byte)251);string image=Convert.ToBase64String(bytes);Check(calls.Present.Invoke(owner,512,512,image)==1,"maximum explicit frame");Array.Fill(bytes,(byte)0);Check(Denied(()=>calls.Present.Invoke(owner,513,512,image))&&Denied(()=>calls.Present.Invoke(owner,512,0,image)),"dimension budget");Check(Denied(()=>calls.Present.Invoke(owner,1,1,image))&&Denied(()=>calls.Present.Invoke(owner,1,1,"AAAA"))&&Denied(()=>calls.Present.Invoke(owner,1,1,"AAAAAA==\n")),"exact canonical pixel length");Check(calls.Present.Invoke(owner,1,1,"AAAAAA==")==2,"failed presents do not advance published revision");Check(calls.Present.Invoke(owner,640,360,Convert.ToBase64String(new byte[640*360*4]))==3,"wide pixels within same byte budget");Check(Denied(()=>calls.Present.Invoke(owner,640,410,Convert.ToBase64String(new byte[640*410*4])))&&Denied(()=>calls.Present.Invoke(owner,641,240,Convert.ToBase64String(new byte[641*240*4]))),"wide area and axis limits");Check(calls.Present.Invoke(owner,1,1,"AAAAAA==")==4,"wide failures keep revision");
  }finally{calls.Close.Invoke(owner);}calls.Close.Invoke(owner);bool closed=false;try{calls.Present.Invoke(owner,1,1,"AAAAAA==");}catch(ObjectDisposedException){closed=true;}Check(closed,"closed owner fenced");string next=calls.Open.Invoke(loop);Check(next!=owner,"explicit new owner after close");calls.Close.Invoke(next);calls.CloseFrame.Invoke(loop);Console.WriteLine("Software surface single owner/budgets/revision/close PASS");return 0;
  """);f.Sync();var report=Build();Output(report,"Software surface single owner/budgets/revision/close PASS");
 }
